profiles = {}

def create(name):
    profiles[name] = {"notifications_enabled": False, "notification_label": "off"}

def enable(name):
    profile = profiles[name]
    profile["notifications_enabled"] = True
    profile["notification_label"] = "on"

def disable(name):
    profile = profiles[name]
    profile["notifications_enabled"] = False
    profile["notification_label"] = "off"

def snapshot(name):
    return dict(profiles[name])
